with flattened as (select id, plan, element from price_tiers lateral view explode(tier_prices) e as element) select case when element >= 86 then 'PREMIUM' else 'STANDARD' end as element_tier, count(case when plan = 'enterprise' then 1 end) as enterprise_count, percentile_approx(element, 0.95) as element_p95 from flattened group by case when element >= 86 then 'PREMIUM' else 'STANDARD' end having element_p95 >= 0
